    "edits": {
      "pos": [
        "Lehni na záda hlavou blízko pevné zdi. Obě dlaně opři o zeď za hlavou v pohodlné výšce, hlavu nech na podložce a kolena pokrč nad kyčlemi. Vzdálenost uprav podle dosahu paží.",
        "Lie on your back with the head near a solid wall. Place both palms on the wall behind the head at a comfortable height, rest the head on the surface and bend the knees above the hips. Adjust the distance to your arm reach."
      ],
      "exe": [
        "Lehce tlač oběma dlaněmi do zdi a střídavě spouštěj jednu patu k podlaze. Vrať nohu před ztrátou klidné polohy zad. Paže zůstávají na místě; nemusíš patou dosáhnout země.",
        "Press lightly into the wall with both palms while alternately lowering one heel toward the floor. Return the leg before the back position changes. Keep the arms still; the heel need not reach the floor."
      ],
      "wat": [
        "Nedotlačuj hlavu do zdi a nezakláněj krk. Vol takový tlak a dosah nohy, při kterém se nezvedají žebra a můžeš plynule dýchat.",
        "Do not drive the head into the wall or extend the neck. Choose wall pressure and leg reach that allow continuous breathing without the ribs lifting."
      ],
      "foc": [
        "Paže drží oporu, pohybují se střídavě nohy. Zapisuj počet podle plánu a zachovej stejné počítání stran; tlak do zdi nemá údaj v kilogramech.",
        "The arms maintain support while the legs alternate. Record the count according to the plan using the same side-counting convention; wall pressure is not recorded in kilograms."
      ],
      "source": {
        "author": "Max Aita / Juggernaut Training Systems",
        "document": "Jerk Manual — wall-press dead bug",
        "url": "https://cdn.jtsstrength.com/wp-content/uploads/2021/09/17061826/JTS_Jerk-Manual-1-uhfzip.pdf",
        "scope": "Jerk Manual, printed page 34: wall-press dead bug with alternating leg extension. This entry retains a bent-knee heel-lowering option; source set/repetition prescription is not universal. Not an official DNS exercise."
      }
    },
