    "edits": {
      "wat": [
        "Zvedni končetiny jen do dosahu, který zvládneš s klidným dechem. Nepřidávej výšku výrazným prohnutím zad nebo přetočením pánve; při ztrátě kontroly obnov obě opory.",
        "Lift the limbs only as far as controlled breathing allows. Do not gain height through marked back arching or pelvic rotation; restore both supports if control is lost."
      ],
      "foc": [
        "Měř sekundy výdrže každé diagonály. Do plánu napiš zvedanou ruku a opačnou nohu; starší označení stran zachovej, i když používalo opěrnou ruku.",
        "Time each diagonal hold in seconds. Name the lifted hand and opposite leg in the plan; retain older side labels even if they used the supporting hand."
      ],
      "pro": [
        "Lehčí možnost: kratší odlehčení nebo nejprve zvednout jen jednu končetinu. Varianta s oporou kolena patří k bird dog; změnu polohy uveď v plánu. Délku výdrže přidávej jen podle kontroly.",
        "Easier option: unload briefly or first lift only one limb. The knee-supported variation belongs to bird dog; note the position change in the plan. Add hold duration only as control allows."
      ],
      "source": {
        "author": "American Council on Exercise",
        "document": "Single Arm, Single Leg Plank",
        "url": "https://www.acefitness.org/resources/everyone/exercise-library/325/single-arm-single-leg-plank/",
        "scope": "The current ACE page confirms the exercise title, no equipment and advanced classification but exposes no execution text. Opposite-limb plank variations are corroborated by NASM coaching guidance; the existing palm-and-toe hold, duration and side explanation remain original Tanmay wording, not an exact reproduced ACE protocol."
      }
    },
