    "edits": {
      "exe": [
        "Veď lano přes hrudník šikmo k opačnému boku a potom kontrolovaně vrať. Pánev i hrudník zachovávají směr vpřed; pohybují se paže.",
        "Draw the rope diagonally across the chest toward the opposite hip, then return under control. Keep pelvis and chest facing forward while the arms move."
      ],
      "foc": [
        "Stažení lana a kontrolovaný návrat je jedno opakování, ne otočení trupu. Zapisuj zátěž stejné kladky a strany podle plánu; označ stranu vysoké kladky, aby záznamy byly srovnatelné.",
        "One diagonal pull and controlled return form a repetition, not a trunk twist. Record the setting on the same pulley and sides as prescribed; identify the high-pulley side for consistent records."
      ],
      "source": {
        "author": "American Council on Exercise",
        "document": "Kneeling Wood Chop",
        "url": "https://www.acefitness.org/resources/everyone/exercise-library/340/kneeling-wood-chop/",
        "scope": "ACE half-kneeling high-cable rope chop: far knee down, near foot forward, arms moving diagonally with pelvis and chest held forward. This is not a rotating standing woodchop. No fixed pause or universal dose is required."
      }
    },
